// scripts/test-inventory.ts — the single source of test counts (guide 08 §5).
// Reads test-results/vitest.json and test-results/playwright.json (generated by
// `npm run test:coverage` and a Playwright run with a JSON reporter) and writes
// docs/evidence/test-inventory.json. Fails when required categories are empty.
import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { execSync } from 'node:child_process';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

// Spec categories that must never report zero tests (guide 08 §7 minimums).
const REQUIRED: Record<string, string[]> = {
  authz: ['authz'],
  authn: ['authn', 'auth'],
  'command-validation': ['command', 'commands', 'roles', 'api.integration'],
  telemetry: ['telemetry', 'poller', 'ingest'],
  automation: ['automation', 'phase5'],
  notification: ['notification', 'notifications', 'webhook', 'phase5'],
  'rate-limit': ['rate-limit', 'ratelimit', 'rate', 'security'],
  retention: ['retention', 'privacy'],
  realtime: ['realtime', 'sse'],
  'status-page': ['status', 'status-page'],
  incident: ['incident'],
  scheduler: ['scheduler'],
  migration: ['migration'],
  queue: ['queue'],
  observability: ['observability', 'metrics'],
  security: ['security', 'xss', 'csrf'],
};

type VitestReport = {
  numTotalTests: number;
  numPassedTests: number;
  testResults?: { name: string; status: string }[];
};

type PlaywrightReport = {
  stats?: { expected: number; skipped: number };
  suites?: unknown;
};

function readJson<T>(p: string): T | null {
  if (!existsSync(p)) return null;
  try {
    return JSON.parse(readFileSync(p, 'utf8')) as T;
  } catch {
    return null;
  }
}

function main(): void {
  const vitest = readJson<VitestReport>(path.join(root, 'test-results', 'vitest.json'));
  const pw = readJson<PlaywrightReport>(path.join(root, 'test-results', 'playwright.json'));

  const categories: Record<string, number> = {};
  if (vitest?.testResults) {
    for (const r of vitest.testResults) {
      for (const [cat, needles] of Object.entries(REQUIRED)) {
        if (needles.some((n) => r.name.toLowerCase().includes(n))) {
          categories[cat] = (categories[cat] ?? 0) + 1;
        }
      }
    }
  }

  const inventory = {
    commit: (() => {
      try {
        return execSync('git rev-parse HEAD', { cwd: root, encoding: 'utf8' }).trim();
      } catch {
        return 'unknown';
      }
    })(),
    vitest: { total: vitest?.numTotalTests ?? 0, passed: vitest?.numPassedTests ?? 0 },
    playwright: { total: pw?.stats?.expected ?? 0, skipped: pw?.stats?.skipped ?? 0 },
    categories,
    generatedAt: new Date().toISOString(),
  };

  const outDir = path.join(root, 'docs', 'evidence');
  mkdirSync(outDir, { recursive: true });
  writeFileSync(path.join(outDir, 'test-inventory.json'), JSON.stringify(inventory, null, 2));

  if (vitest) {
    const missing = Object.keys(REQUIRED).filter((c) => !categories[c]);
    if (missing.length > 0) {
      console.error(
        `test-inventory: no test file matched required categories: ${missing.join(', ')}`,
      );
      process.exit(1);
    }
  } else {
    console.warn(
      'test-inventory: test-results/vitest.json missing — run `npm run test:coverage` first.',
    );
  }
  console.log('test-inventory written to docs/evidence/test-inventory.json');
}

main();
